function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#2a1f14', A='#e0a820', AL='#f4d060', AD='#b07818', V='#6b4a8a';
  for (let y=8;y<56;y++) for (let x=8;x<56;x++) {
    const dx=x-32, dy=y-32, r=Math.sqrt(dx*dx+dy*dy);
    if (r<=24&&r>=18) px(x,y,1,1,A);
    else if (r<18) px(x,y,1,1,V);
  }
  for (let y=8;y<56;y++) for (let x=8;x<56;x++) {
    const dx=x-32, dy=y-32;
    if (dx*dx+dy*dy<=24*24 && dx*dx+dy*dy>=22*22) px(x,y,1,1,O);
  }
  px(30,12,4,4,AL); px(44,28,3,3,AL); px(18,40,3,3,AD);
}
